const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { action: 'unknown', name: null, cnic: null, room: null, fee: null, rent_status: null, contact_number: null, address: null, job_student: null, university: null, company: null, security: null, rent_owner1: null, rent_owner2: null, notes: 'PARSE_ERROR', query_type: null, requested_field: null };
}

function normalizeRoom(value) {
  if (value === null || value === undefined || value === '') return null;
  const text = String(value).trim();
  const numericRoom = text.match(/\b\d+\b/);
  return numericRoom ? numericRoom[0] : text;
}

function normalizeName(value) {
  if (value === null || value === undefined || value === '') return null;
  return String(value).trim().replace(/\s+/g, ' ');
}

parsed.name = normalizeName(parsed.name);
parsed.cnic = parsed.cnic ? String(parsed.cnic).trim().replace(/\D/g, '') : null;
parsed.room = normalizeRoom(parsed.room);
parsed.residentKey = parsed.name && parsed.room ? `${parsed.name}|${parsed.room}` : '';

let senderPhone = null;
try { senderPhone = $('Edit Fields2').first().json.senderPhone; } catch (e) {}
if (!senderPhone) {
  try { senderPhone = $('Edit Fields').first().json.senderPhone; } catch (e) {}
}
parsed.senderPhone = senderPhone;

return [{ json: parsed }];

const c = $('Code in JavaScript').item.json;

// For update/vacate, get the merged record
// so the reply reflects the complete saved resident data.
let saved = null;

try {
  saved = $('Merge Fields').item.json;
} catch (e) {
  saved = null;
}

function value(v, fallback = 'not recorded') {
  return v !== null && v !== undefined && String(v).trim() !== ''
    ? String(v)
    : fallback;
}

let msg;

if (c.action === 'new') {

  const feeText = c.fee
    ? `\nRent: Rs ${c.fee}/month`
    : '';

  msg =
`✅ Added successfully

Name: ${value(c.name)}
Room: ${value(c.room)}
CNIC: ${value(c.cnic)}${feeText}`;

} else if (c.action === 'update') {

  const r = saved || c;

  msg =
`✅ Updated successfully

Name: ${value(r.name)}
Room: ${value(r.room)}
CNIC: ${value(r.cnic)}
Rent: Rs ${value(r.fee)}
Rent Status: ${value(r.rent_status)}
Contact: ${value(r.contact_number)}
Address: ${value(r.address)}
Status: ${value(r.personStatus)}`;

} else if (c.action === 'vacate') {

  const r = saved || c;

  msg =
`🚪 Resident marked vacated

Name: ${value(r.name)}
Room: ${value(r.room)}
CNIC: ${value(r.cnic)}
Rent: Rs ${value(r.fee)}
Rent Status: ${value(r.rent_status)}
Contact: ${value(r.contact_number)}
Address: ${value(r.address)}
Status: ${value(r.personStatus)}`;

} else {

  msg = 'Saved.';
}

return [{
  json: {
    replyMessage: msg,
    senderPhone: c.senderPhone
  }
}];

const extracted = $('Code in JavaScript').item.json;
const rows = $input.all();

function normalizeRoom(value) {
  if (value === null || value === undefined || value === '') return null;
  const text = String(value).trim();
  const numericRoom = text.match(/\b\d+\b/);
  return numericRoom ? numericRoom[0] : text;
}

function normalizeName(value) {
  if (value === null || value === undefined || value === '') return null;
  return String(value).trim().replace(/\s+/g, ' ').toLowerCase();
}

const targetName = normalizeName(extracted.name);
const targetRoom = normalizeRoom(extracted.room);

const nameMatches = rows
  .map(item => item.json)
  .filter(row => normalizeName(row['Name']) === targetName);

// No resident with this name
if (nameMatches.length === 0) {
  return [{
    json: {
      notFound: true,
      name: extracted.name,
      room: extracted.room,
      action: extracted.action,
      senderPhone: extracted.senderPhone
    }
  }];
}

// Exactly one resident with this name
// Room is NOT required — use the resident's canonical room.
let existing = null;

if (nameMatches.length === 1) {
  existing = nameMatches[0];
}

// Multiple residents with same name
// Room is now required to identify the correct one.
if (nameMatches.length > 1) {
  if (!targetRoom) {
    return [{
      json: {
        notFound: true,
        ambiguous: true,
        name: extracted.name,
        room: null,
        action: extracted.action,
        senderPhone: extracted.senderPhone,
        clarificationMessage:
          `I found multiple residents named ${extracted.name}. Please include the room number so I know which resident you mean.`
      }
    }];
  }

  const roomMatches = nameMatches.filter(row =>
    normalizeRoom(row['Room no.']) === targetRoom
  );

  if (roomMatches.length !== 1) {
    return [{
      json: {
        notFound: true,
        ambiguous: true,
        name: extracted.name,
        room: targetRoom,
        action: extracted.action,
        senderPhone: extracted.senderPhone,
        clarificationMessage:
          `I found multiple residents named ${extracted.name}, and I couldn't uniquely match Room ${targetRoom}. Please provide the correct room number.`
      }
    }];
  }

  existing = roomMatches[0];
}

function pick(newVal, oldVal, fallback) {
  if (newVal !== null && newVal !== undefined && newVal !== '') {
    return newVal;
  }

  if (oldVal !== undefined && oldVal !== null && oldVal !== '') {
    return oldVal;
  }

  return fallback;
}

const canonicalName = existing['Name'] || extracted.name;

const canonicalRoom = normalizeRoom(
  existing['Room no.']
);

const merged = {
  notFound: false,
  senderPhone: extracted.senderPhone,

  residentKey:
    canonicalName && canonicalRoom
      ? `${canonicalName}|${canonicalRoom}`
      : extracted.residentKey,

  name: canonicalName,
  room: canonicalRoom,

  cnic: pick(extracted.cnic, existing['CNIC'], ''),
  contact_number: pick(
    extracted.contact_number,
    existing['Contact no.'],
    ''
  ),
  fee: pick(
    extracted.fee,
    existing['Room Rent'],
    ''
  ),
  rent_status: pick(
    extracted.rent_status,
    existing['Rent Status'],
    'Pending'
  ),
  address: pick(
    extracted.address,
    existing['Personal Address'],
    ''
  ),

  personStatus:
    existing["Person's Status"] || 'Active',

  // Keep the complete existing row available
  existingRow: existing
};

if (extracted.action === 'vacate') {
  merged.personStatus = 'Vacated';
}

return [{ json: merged }];

const p = $input.first().json;

let error = null;

const validActions = ['new', 'update', 'vacate', 'query', 'pdf'];
const validQueryTypes = [
  'resident_lookup',
  'unpaid_list',
  'total_income'
];

// --------------------------------------------------
// BASIC ACTION VALIDATION
// --------------------------------------------------
if (p.notes === 'PARSE_ERROR' || !validActions.includes(p.action)) {

  error =
    "Sorry, I couldn't understand that message. Try something like:\n" +
    "• 'new student Ahmed room 101 rent 15000'\n" +
    "• 'update Ahmed room 101 rent to 15000'\n" +
    "• 'Ahmed room 101 left'";


// --------------------------------------------------
// PDF
// --------------------------------------------------
} else if (p.action === 'pdf') {

  // PDF does not require resident information.
  error = null;


// --------------------------------------------------
// NEW RESIDENT
// --------------------------------------------------
} else if (p.action === 'new' && (!p.name || !p.room)) {

  // A NEW resident still requires BOTH name and room.
  error =
    "To add a new resident I need both a name and room number, " +
    "e.g. 'new student Ahmed room 101 rent 15000'.";


// --------------------------------------------------
// CNIC VALIDATION
// --------------------------------------------------
} else if (
  p.cnic &&
  !/^\d{13}$/.test(String(p.cnic))
) {

  error =
    "The CNIC should contain 13 digits. You can send it with or without dashes, " +
    "for example 35202-1234567-1.";


// --------------------------------------------------
// UPDATE / VACATE
// --------------------------------------------------
} else if (
  (p.action === 'update' || p.action === 'vacate') &&
  !p.name
) {

  // IMPORTANT:
  // Room is NOT required here.
  //
  // If there is exactly one resident with this name,
  // the downstream resident-matching logic can use that
  // resident's existing room from Google Sheets.
  //
  // If multiple residents have the same name, the
  // matching logic can request the room for clarification.

  error =
    "I need the resident's name to do that. " +
    "For example: 'Saleem ka rent 5500 kar do'.";


// --------------------------------------------------
// QUERY
// --------------------------------------------------
} else if (p.action === 'query') {

  if (!validQueryTypes.includes(p.query_type)) {

    error =
      "I couldn't identify the lookup or report you want. " +
      "Try: 'What room is Ahmed Khan in?', " +
      "'Who hasn't paid rent?', or " +
      "'What is the total rent income?'.";

  } else if (
    p.query_type === 'resident_lookup' &&
    !p.name
  ) {

    error =
      "I need the resident's name for that lookup. " +
      "Try: 'What room is Ahmed Khan in?'";
  }
}


// --------------------------------------------------
// RETURN
// --------------------------------------------------
return [
  {
    json: {
      ...p,
      validationError: error
    }
  }
];

const c = $input.first().json;
const msg = `⚠️ I couldn't find a resident named "${c.name || '?'}" in room ${c.room || '?'}. If this is a new resident, try: 'new student ${c.name || 'Name'} room ${c.room || '101'} rent 15000'. If they should already exist, please double check the spelling of the name and room.`;
return [{ json: { replyMessage: msg, senderPhone: c.senderPhone } }];

const query = $('Code in JavaScript').item.json;
const rows = $input.all().map(item => item.json || {});

function norm(value) {
  return String(value ?? '').trim().replace(/\s+/g, ' ').toLowerCase();
}

function room(value) {
  const text = String(value ?? '').trim();
  const m = text.match(/\b\d+\b/);
  return m ? m[0] : text;
}

function money(value) {
  const n = Number(String(value ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : 0;
}

const activeRows = rows.filter(r => norm(r["Person's Status"]) !== 'vacated');
let reply;

if (query.query_type === 'resident_lookup') {
  const target = norm(query.name);
  const matches = rows.filter(r => norm(r['Name']) === target);

  if (!matches.length) {
    reply = `⚠️ I couldn't find a resident named "${query.name || '?'}" in the hostel records.`;
  } else if (matches.length > 1) {
    const list = matches.map(r => {
      const n = r['Name'] || query.name;
      const rm = room(r['Room no.']) || '?';
      const cnic = r['CNIC'] || '?';
      const rent = r['Room Rent'] || '?';
      const status = r['Rent Status'] || '?';
      return `${n} — Room ${rm}, CNIC ${cnic}, Rent Rs ${rent}, Status ${status}`;
    }).join('\n');
    reply = `I found multiple records for ${query.name}:\n${list}\nPlease include the room number if you want a specific record.`;
  } else {
    const r = matches[0];
    const requested = query.requested_field || 'all';
    const name = r['Name'] || query.name;
    const rm = room(r['Room no.']) || '?';

    if (requested === 'room') {
      reply = `${name} is in Room ${rm}.`;
    } else if (requested === 'rent') {
      reply = `${name}'s rent is Rs ${r['Room Rent'] || 0}/month.`;
    } else if (requested === 'rent_status') {
      reply = `${name}'s rent status is ${r['Rent Status'] || 'Unknown'}.`;
    } else if (requested === 'contact_number') {
      reply = `${name}'s contact number is ${r['Contact no.'] || 'not recorded'}.`;
    } else if (requested === 'address') {
      reply = `${name}'s address is ${r['Personal Address'] || 'not recorded'}.`;
    } else if (requested === 'cnic') {
      reply = `${name}'s CNIC is ${r['CNIC'] || 'not recorded'}.`;
    } else if (requested === 'security') {
      reply = `${name}'s security is Rs ${r['Security'] || 0}.`;
    } else if (requested === 'university') {
      reply = `${name}'s university is ${r['University'] || 'not recorded'}.`;
    } else if (requested === 'company') {
      reply = `${name}'s company is ${r['Company'] || 'not recorded'}.`;
    } else if (requested === 'job_student') {
      reply = `${name} is recorded as ${r['JOB / Student'] || 'not recorded'}.`;
    } else if (requested === 'rent_owner1') {
      reply = `${name}'s rent paid to Owner 1 is Rs ${r['Rent paid to Owner 1'] || 0}.`;
    } else if (requested === 'rent_owner2') {
      reply = `${name}'s rent paid to Owner 2 is Rs ${r['Rent paid to Owner 2'] || 0}.`;
    } else {
      reply = `📋 ${name}\nRoom: ${rm}\nCNIC: ${r['CNIC'] || 'not recorded'}\nRent: Rs ${r['Room Rent'] || 0}/month\nRent status: ${r['Rent Status'] || 'Unknown'}\nContact: ${r['Contact no.'] || 'not recorded'}\nAddress: ${r['Personal Address'] || 'not recorded'}\nSecurity: Rs ${r['Security'] || 0}\nJob/Student: ${r['JOB / Student'] || 'not recorded'}\nUniversity: ${r['University'] || 'not recorded'}\nCompany: ${r['Company'] || 'not recorded'}\nOwner 1 Rent: Rs ${r['Rent paid to Owner 1'] || 0}\nOwner 2 Rent: Rs ${r['Rent paid to Owner 2'] || 0}\nStatus: ${r["Person's Status"] || 'Active'}`;
    }
  }
} else if (query.query_type === 'unpaid_list') {
  const unpaid = activeRows.filter(r => norm(r['Rent Status']) !== 'paid');
  if (!unpaid.length) {
    reply = '✅ All active residents have paid their rent.';
  } else {
    const lines = unpaid.map((r, i) => `${i + 1}. ${r['Name'] || 'Unknown'} — Room ${room(r['Room no.']) || '?'} — Rs ${r['Room Rent'] || 0}`);
    reply = `💰 Residents with unpaid/pending rent (${unpaid.length}):\n${lines.join('\n')}`;
  }
} else if (query.query_type === 'total_income') {
  const total = activeRows.reduce((sum, r) => sum + money(r['Room Rent']), 0);
  reply = `💰 Total monthly rent income from active residents: Rs ${total.toLocaleString('en-PK')}.`;
} else {
  reply = "I couldn't determine which report you want.";
}

return [{ json: { replyMessage: reply, senderPhone: query.senderPhone } }];

const incoming = $('Code in JavaScript').item.json;
const rows = $input.all().map(i => i.json);
function norm(value) { return value === null || value === undefined ? '' : String(value).trim().toLowerCase(); }
function room(value) { const text = norm(value); const m = text.match(/\b\d+\b/); return m ? m[0] : text; }
function isActive(value) { const s = norm(value); return s === '' || ['active','occupied','current'].includes(s); }
const targetRoom = room(incoming.room);
const targetCnic = norm(incoming.cnic);
const activeRoomConflict = rows.find(r => room(r['Room no.']) === targetRoom && isActive(r["Person's Status"]));
const cnicConflict = targetCnic ? rows.find(r => norm(r['CNIC']) === targetCnic) : null;
let conflictType = null, conflictRow = null;
if (activeRoomConflict) { conflictType = 'room'; conflictRow = activeRoomConflict; } else if (cnicConflict) { conflictType = 'cnic'; conflictRow = cnicConflict; }
return [{ json: { ...incoming, canCreate: !conflictType, conflictType, conflictName: conflictRow ? (conflictRow['Name'] || '') : '', conflictRoom: conflictRow ? (conflictRow['Room no.'] || '') : '', conflictCnic: conflictRow ? (conflictRow['CNIC'] || '') : '' } }];

const c = $input.first().json;
let msg;
if (c.conflictType === 'room') msg = `⚠️ Room ${c.room} is already occupied by ${c.conflictName || 'another resident'}. I did not add ${c.name}. Please choose an available room.`;
else if (c.conflictType === 'cnic') msg = `⚠️ This CNIC is already registered${c.conflictName ? ` to ${c.conflictName}` : ''}${c.conflictRoom ? ` in room ${c.conflictRoom}` : ''}. I did not create a duplicate resident.`;
else msg = '⚠️ I could not add the resident because the request conflicts with existing resident data.';
return [{ json: { replyMessage: msg, senderPhone: c.senderPhone } }];
